# Search facets used by the local filter engine. These are catalog labels, not nutrition claims.
for recipe in RECIPES:
    tags = set(recipe["tags"]) | {"вкусное", "домашнее"}
    if recipe["minutes"] <= 20:
        tags.add("быстро")
    ingredients = {entry["name"] for entry in recipe["ingredients"]}
    if ingredients.intersection({"курица", "фарш", "котлеты"}):
        tags.add("мясное")
    if recipe["id"] == "pasta-cutlets":
        tags.add("котлеты")
    elif "рыба" in ingredients:
        tags.add("рыбное")
    else:
        tags.add("вегетарианское")
    if recipe["method"] != "духовка":
        tags.add("без духовки")
    recipe["tags"] = sorted(tags)
